-- For each case of cases.sql, one row comparing komira's file (komira/<file>,
-- written by run_sql) with DuckDB's (<file>, written by the same line): the
-- rows of each, the rows in one and not the other (as multisets, NULL equal to
-- NULL), and the columns' names and types as DuckDB reads them. For a CSV or
-- JSON file with no compression, also whether the two files hold the same
-- bytes (`same_bytes`).
COPY (SELECT (SELECT count(*) FROM 'komira/typed_default.parquet') AS komira_rows, (SELECT count(*) FROM 'typed_default.parquet') AS duckdb_rows, (SELECT count(*) FROM (SELECT * FROM 'komira/typed_default.parquet' EXCEPT ALL SELECT * FROM 'typed_default.parquet')) + (SELECT count(*) FROM (SELECT * FROM 'typed_default.parquet' EXCEPT ALL SELECT * FROM 'komira/typed_default.parquet')) AS differing_rows, (SELECT string_agg(column_name || ' ' || column_type, ', ') FROM (DESCRIBE SELECT * FROM 'komira/typed_default.parquet')) AS komira_columns, (SELECT string_agg(column_name || ' ' || column_type, ', ') FROM (DESCRIBE SELECT * FROM 'typed_default.parquet')) AS duckdb_columns) TO 'typed_default.check.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT (SELECT count(*) FROM 'komira/typed_zstd.parquet') AS komira_rows, (SELECT count(*) FROM 'typed_zstd.parquet') AS duckdb_rows, (SELECT count(*) FROM (SELECT * FROM 'komira/typed_zstd.parquet' EXCEPT ALL SELECT * FROM 'typed_zstd.parquet')) + (SELECT count(*) FROM (SELECT * FROM 'typed_zstd.parquet' EXCEPT ALL SELECT * FROM 'komira/typed_zstd.parquet')) AS differing_rows, (SELECT string_agg(column_name || ' ' || column_type, ', ') FROM (DESCRIBE SELECT * FROM 'komira/typed_zstd.parquet')) AS komira_columns, (SELECT string_agg(column_name || ' ' || column_type, ', ') FROM (DESCRIBE SELECT * FROM 'typed_zstd.parquet')) AS duckdb_columns) TO 'typed_zstd.check.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
