COPY (SELECT (SELECT count(*) FROM 'komira/typed_csv.csv') AS komira_rows, (SELECT count(*) FROM 'typed_csv.csv') AS duckdb_rows, (SELECT count(*) FROM (SELECT * FROM 'komira/typed_csv.csv' EXCEPT ALL SELECT * FROM 'typed_csv.csv')) + (SELECT count(*) FROM (SELECT * FROM 'typed_csv.csv' EXCEPT ALL SELECT * FROM 'komira/typed_csv.csv')) AS differing_rows, (SELECT string_agg(column_name || ' ' || column_type, ', ') FROM (DESCRIBE SELECT * FROM 'komira/typed_csv.csv')) AS komira_columns, (SELECT string_agg(column_name || ' ' || column_type, ', ') FROM (DESCRIBE SELECT * FROM 'typed_csv.csv')) AS duckdb_columns, (SELECT content FROM read_blob('komira/typed_csv.csv')) = (SELECT content FROM read_blob('typed_csv.csv')) AS same_bytes) TO 'typed_csv.check.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
